from django.db import migrations, models
from django.utils.text import slugify


def generate_slugs(apps, schema_editor):
    Post = apps.get_model('blog', 'post')

    for item in Post.objects.all().order_by('id'):
        base_slug = slugify(item.title)[:90] or f'post-{item.id}'
        slug = base_slug
        counter = 1

        while Post.objects.filter(slug=slug).exclude(pk=item.pk).exists():
            slug = f'{base_slug}-{counter}'
            counter += 1

        item.slug = slug
        item.save(update_fields=['slug'])


class Migration(migrations.Migration):
    dependencies = [
        ('blog', '0003_post_created_at'),
    ]

    operations = [
        migrations.AddField(
            model_name='post',
            name='slug',
            field=models.SlugField(
                max_length=100,
                unique=True,
                null=True,
            ),
        ),
        migrations.RunPython(generate_slugs, migrations.RunPython.noop),
        migrations.AlterField(
            model_name='post',
            name='slug',
            field=models.SlugField(max_length=100, unique=True),
        ),
    ]
